        if self.dots == 2.0 {
            ticks = MidiUtils.applyDot(ticks, true)
        } else if self.dots == 1.0 {
            ticks = MidiUtils.applyDot(ticks, false)
        }
        if self.tupletDenominator > 0 && self.tupletNumerator >= 0 {
            ticks = MidiUtils.applyTuplet(ticks, self.tupletNumerator, self.tupletDenominator)
        }
        return ticks
    }

    public func updateDurations() {
        let ticks: Double = self._calculateDuration()
        self.playbackDuration = ticks
        switch self.graceType {
        case GraceType.BeforeBeat, GraceType.OnBeat:
            switch self.duration {
            case Duration.Sixteenth:
                self.playbackDuration = MidiUtils.toTicks(Duration.SixtyFourth)
            case Duration.ThirtySecond:
                self.playbackDuration = MidiUtils.toTicks(Duration.OneHundredTwentyEighth)
            default:
                self.playbackDuration = MidiUtils.toTicks(Duration.ThirtySecond)
            }
            self.displayDuration = 0.0
        case GraceType.BendGrace:
            self.playbackDuration /= 2.0
            self.displayDuration = 0.0
        default:
            self.displayDuration = ticks
            let previous: Beat? = self.previousBeat
            if TypeHelper.isTruthy(TypeHelper.isTruthy(previous) && previous!.graceType == GraceType.BendGrace) {
                self.playbackDuration = previous!.playbackDuration
            }
        }
    }

