                        points!.splice(1.0, 1.0)
                    } else if (origin.value > middle1.value && middle1.value < destination.value) || (origin.value < middle1.value && middle1.value > destination.value) {
                        self.whammyBarType = WhammyType.Dip
                        if middle1.offset == middle2.offset || displayMode == NotationMode.SongBook {
                            points!.splice(2.0, 1.0)
                        }
                    } else if origin.value == middle1.value && middle1.value == destination.value {
                        if origin.value != 0.0 && !self.isContinuedWhammy {
                            self.whammyBarType = WhammyType.Predive
                        } else {
                            self.whammyBarType = WhammyType.Hold
                        }
                        points!.splice(2.0, 1.0)
                        points!.splice(1.0, 1.0)
                    }
                }
            } else if points!.length == 3.0 {
                let origin: BendPoint = points![0]
                let middle: BendPoint = points![1]
                let destination: BendPoint = points![2]
                if (origin.value < middle.value && middle.value < destination.value) || (origin.value > middle.value && middle.value > destination.value) {
                    if origin.value != 0.0 && !self.isContinuedWhammy {
                        self.whammyBarType = WhammyType.PrediveDive
                    } else {
                        self.whammyBarType = WhammyType.Dive
                    }
                    points!.splice(1.0, 1.0)
                } else if (origin.value > middle.value && middle.value < destination.value) || (origin.value < middle.value && middle.value > destination.value) {
                    self.whammyBarType = WhammyType.Dip
                } else if origin.value == middle.value && middle.value == destination.value {
                    if origin.value != 0.0 && !self.isContinuedWhammy {
                        self.whammyBarType = WhammyType.Predive
                    } else {
                        self.whammyBarType = WhammyType.Hold
                    }
                    points!.splice(1.0, 1.0)
                }
            } else if points!.length == 2.0 {
                let origin: BendPoint = points![0]
                let destination: BendPoint = points![1]
                if origin.value < destination.value || origin.value > destination.value {
                    if origin.value != 0.0 && !self.isContinuedWhammy {
                        self.whammyBarType = WhammyType.PrediveDive
                    } else {
                        self.whammyBarType = WhammyType.Dive
                    }
                } else if origin.value == destination.value {
                    if origin.value != 0.0 && !self.isContinuedWhammy {
                        self.whammyBarType = WhammyType.Predive
                    } else {
                        self.whammyBarType = WhammyType.Hold
                    }
                }
            }
        }
        self.updateDurations()
        if needCopyBeatForBend {
            let cloneBeat: Beat = BeatCloner.clone(self)
            cloneBeat.id = jsPostInc(&Beat._globalBeatId)
            cloneBeat.pickStroke = PickStroke.None
            do {
                var i: Double = 0.0
                var j: Double = cloneBeat.notes.length
                while i < j {
                    let cloneNote: Note = cloneBeat.notes[(i).toInt()]
                    let note: Note = self.notes[(i).toInt()]
                    cloneNote.bendType = BendType.None
                    cloneNote.maxBendPoint = nil
                    cloneNote.bendPoints = nil
                    cloneNote.bendStyle = BendStyle.Default
                    cloneNote.id = jsPostInc(&Note.globalNoteId)
                    if note.isTieOrigin {
                        cloneNote.tieDestination = note.tieDestination!
                        note.tieDestination!.tieOrigin = cloneNote
                    }
                    if note.isTieDestination {
                        cloneNote.tieOrigin = TypeHelper.isTruthy(note.tieOrigin) ? note.tieOrigin! : nil
                        note.tieOrigin!.tieDestination = cloneNote
                    }
                    if note.hasBend && note.isTieOrigin {
                        let tieDestination: Note? = Note.findTieOrigin(note)
                        if TypeHelper.isTruthy(TypeHelper.isTruthy(tieDestination) && tieDestination!.hasBend) {
                            cloneNote.bendType = BendType.Hold
                            let lastPoint: BendPoint = note.bendPoints![(note.bendPoints!.length - 1.0).toInt()]
                            cloneNote.addBendPoint(BendPoint(0.0, lastPoint.value))
                            cloneNote.addBendPoint(BendPoint(BendPoint.MaxPosition, lastPoint.value))
                        }
                    }
                    cloneNote.isTieDestination = true
                    i += 1
                }
            }
            self.graceType = GraceType.BendGrace
            self.graceGroup = GraceGroup()
            self.graceGroup!.addBeat(self)
            self.graceGroup!.isComplete = true
            self.graceGroup!.finish()
            self.updateDurations()
            self.voice.insertBeat(self, cloneBeat)
            cloneBeat.graceGroup = GraceGroup()
            cloneBeat.graceGroup!.addBeat(self)
            cloneBeat.graceGroup!.isComplete = true
            cloneBeat.graceGroup!.finish()
        }
    }

    /**
     * Checks whether the current beat is timewise before the given beat.
     */
    public func isBefore(_ beat: Beat) -> Bool {
        return (self.voice.bar.index < beat.voice.bar.index || (beat.voice.bar.index == self.voice.bar.index && self.index < beat.index))
    }

    /**
     * Checks whether the current beat is timewise after the given beat.
     */
    public func isAfter(_ beat: Beat) -> Bool {
        return (self.voice.bar.index > beat.voice.bar.index || (beat.voice.bar.index == self.voice.bar.index && self.index > beat.index))
    }

    public func hasNoteOnString(_ noteString: Double) -> Bool {
        return self.noteStringLookup.has(noteString)
    }

    public func getNoteWithRealValue(_ noteRealValue: Double) -> Note? {
        if self.noteValueLookup.has(noteRealValue) {
            return self.noteValueLookup.get(noteRealValue)!
        }
        return nil
    }

    public func chain(_ sharedDataBag: Map<String, Any?>? = nil) {
        for n in self.notes {
            self.noteValueLookup.set(n.realValue, n)
            n.chain(sharedDataBag)
        }
    }

    public init() {}
}

/**
 * Lists the different modes on how beaming for a beat should be done.
 */
public enum BeatBeamingMode: Int, IAlphaTabEnum, CaseIterable {
    /**
     * Automatic beaming based on the timing rules.
     */
    case Auto = 0
    /**
     * Force a split to the next beat.
     */
    case ForceSplitToNext = 1
    /**
     * Force a merge with the next beat.
     */
    case ForceMergeWithNext = 2
    /**
     * Force a split to the next beat on the secondary beam.
     */
    case ForceSplitOnSecondaryToNext = 3
}

/**
 * Lists all graphical sub elements within a  which can be styled via
 */
public enum BeatSubElement: Int, IAlphaTabEnum, CaseIterable {
    /**
     * The effects and annotations shown in dedicated effect bands above the staves (e.g. fermata).
     * Only applies to items which are on beat level but not any individual note level effects.
     */
    case Effects = 0
    /**
     * The stems drawn for note heads in this beat on the standard notation staff.
     */
    case StandardNotationStem = 1
    /**
     * The flags drawn for note heads in this beat on the standard notation staff.
     */
    case StandardNotationFlags = 2
    /**
     * The beams drawn between this and the next beat on the standard notation staff.
     */
    case StandardNotationBeams = 3
    /**
     * The tuplet drawn on the standard notation staff (the first beat affects the whole tuplet if grouped).
     */
    case StandardNotationTuplet = 4
    /**
     * The effects and annotations applied to this beat on the standard notation staff (e.g. brushes).
     * Only applies to items which are on beat level but not any individual note level effects.
     */
    case StandardNotationEffects = 5
    /**
     * The rest symbol on the standard notation staff.
     */
    case StandardNotationRests = 6
    /**
     * The stems drawn for note heads in this beat on the guitar tab staff.
     */
    case GuitarTabStem = 7
    /**
     * The flags drawn for note heads in this beat on the guitar tab staff.
     */
    case GuitarTabFlags = 8
    /**
     * The beams drawn between this and the next beat on the guitar tab staff.
     */
    case GuitarTabBeams = 9
    /**
     * The tuplet drawn on the guitar tab staff (the first beat affects the whole tuplet if grouped).
     */
    case GuitarTabTuplet = 10
    /**
     * The effects and annotations applied to this beat on the guitar tab staff (e.g. brushes).
     * Only applies to items which are on beat level but not any individual note level effects.
     */
    case GuitarTabEffects = 11
    /**
     * The rest symbol on the guitar tab staff.
     */
    case GuitarTabRests = 12
    /**
     * The stems drawn for note heads in this beat on the slash staff.
     */
    case SlashStem = 13
    /**
     * The flags drawn for note heads in this beat on the slash staff.
     */
    case SlashFlags = 14
    /**
     * The beams drawn between this and the next beat on the slash staff.
     */
    case SlashBeams = 15
    /**
     * The tuplet drawn on the slash staff (the first beat affects the whole tuplet if grouped).
     */
    case SlashTuplet = 16
    /**
     * The rest symbol on the slash staff.
     */
    case SlashRests = 17
    /**
     * The effects and annotations applied to this beat on the slash staff (e.g. brushes).
     * Only applies to items which are on beat level but not any individual note level effects.
     */
    case SlashEffects = 18
    /**
     * The duration lines drawn for this beat on the numbered notation staff.
     */
    case NumberedDuration = 19
    /**
     * The effects and annotations applied to this beat on the numbered notation staff (e.g. brushes).
     * Only applies to items which are on beat level but not any individual note level effects.
     */
    case NumberedEffects = 20
    /**
     * The rest (0) on the numbered notation staff.
     */
    case NumberedRests = 21
    /**
     * The tuplet drawn on the numbered notation staff (the first beat affects the whole tuplet if grouped).
     */
    case NumberedTuplet = 22
}

/**
 * Defines the custom styles for beats.
 */
public final class BeatStyle: ElementStyle<BeatSubElement> {
    public override init() {
        super.init()
    }
}
